.info-button { width: 1.35rem; height: 1.35rem; border: 1px solid #65746a; border-radius: 50%; background: transparent; font-size: .72rem; font-weight: 700; }
#tax-tooltip { font-size: .75rem; color: #67736a; }
.choice-heading, .size-heading { display: flex; justify-content: space-between; align-items: center; font-size: .85rem; margin-bottom: .75rem; }
.choice-heading strong { font-weight: 500; color: #68736a; }
.choice-group { border-top: 1px solid #d5dbd2; padding-top: 1.25rem; }
