            aria-label={`${index + 1} of ${slides.length}`}
            hidden={active !== index}
            aria-hidden={active !== index}
            aria-current={active === index ? 'true' : undefined}
          >
            <div className="illustrated-shoe" aria-label={slide.label} role="img">
              <span className="shoe-upper" />
              <span className="shoe-sole" />
              <span className="shoe-lace" />
            </div>
            <span className="slide-label">{String(index + 1).padStart(2, '0')} / {String(slides.length).padStart(2, '0')}</span>
          </div>
        ))}
        <button className="carousel-button previous" type="button" onClick={() => move(-1)} aria-label="Previous product photo">←</button>
        <button className="carousel-button next" type="button" onClick={() => move(1)} aria-label="Next product photo">→</button>
      </div>
    </section>
  )
}

function SizeGuide({ onClose }) {
  const dialogRef = useRef(null)
  const [unit, setUnit] = useState('us')
  const [length, setLength] = useState('')
  const [result, setResult] = useState('')

  useEffect(() => {
    dialogRef.current?.focus()
    const onKeyDown = (event) => {
      if (event.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [onClose])

  const calculate = (event) => {
    event.preventDefault()
    const numericLength = Number(length)
    setResult(numericLength >= 25.5 ? `We recommend size ${unit === 'eu' ? '41' : '8'}.` : 'Enter your foot length to find your size.')
  }

  return (
    <div className="modal-backdrop">
      <div className="size-dialog" role="dialog" aria-modal="true" aria-labelledby="size-guide-title" tabIndex="-1" ref={dialogRef}>
        <button className="modal-close" type="button" onClick={onClose} aria-label="Close size guide">×</button>
        <p className="eyebrow">Find your fit</p>
        <h2 id="size-guide-title">Size guide</h2>
        <p>Measure from the back of your heel to the tip of your longest toe.</p>
        <form onSubmit={calculate}>
          <label htmlFor="foot-length">Foot length</label>
          <div className="measure-row">
            <input id="foot-length" name="foot-length" type="number" min="1" step="0.1" value={length} onChange={(event) => setLength(event.target.value)} aria-label="Foot length" />
            <span>cm</span>
          </div>
          <fieldset>
            <legend>Size system</legend>
            <label><input type="radio" name="unit" value="us" checked={unit === 'us'} onChange={() => setUnit('us')} /> US</label>
            <label><input type="radio" name="unit" value="eu" checked={unit === 'eu'} onChange={() => setUnit('eu')} /> EU</label>
          </fieldset>
          <button className="primary-button" type="submit">Find my size</button>
        </form>
        {result && <p className="size-result" role="status">{result}</p>}
      </div>
    </div>
  )
}

function ProductChoices({ onAdd }) {
  const [color, setColor] = useState('Blue')
  const [size, setSize] = useState('')
  const [sizeOpen, setSizeOpen] = useState(false)
  const [quantity, setQuantity] = useState(1)
  const [wishlist, setWishlist] = useState(false)
  const [guideOpen, setGuideOpen] = useState(false)
  const [message, setMessage] = useState('')
  const [activeSize, setActiveSize] = useState(0)
  const [taxVisible, setTaxVisible] = useState(false)
  const guideButtonRef = useRef(null)
  const selectedSize = sizes.find((item) => item.value === size)

  const updateQuantity = (next) => setQuantity(Math.max(1, Number.isFinite(next) ? next : 1))
  const addToCart = () => {
    if (!selectedSize?.available) {
      setMessage('Please select a size before adding to cart.')
      return
    }
    onAdd(quantity)
    setMessage(`${quantity} pair${quantity === 1 ? '' : 's'} added to cart.`)
  }
  const closeGuide = () => {
    setGuideOpen(false)
    requestAnimationFrame(() => guideButtonRef.current?.focus())
  }
  const handleSizeKeyDown = (event) => {
    if (event.key === 'Escape') {
      setSizeOpen(false)
    } else if (event.key === 'Enter') {
      setSizeOpen((open) => {
        if (open) {
          const option = sizes[activeSize]
          if (option.available) setSize(option.value)
          return false
        }
        return true
      })
    } else if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowDown') {
      event.preventDefault()
      setSizeOpen(true)
      setActiveSize((index) => Math.min(index + 1, sizes.length - 1))
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      setSizeOpen(true)
      setActiveSize((index) => Math.max(index - 1, 0))
    }
  }

  return (
    <div className="product-panel">
      <p className="eyebrow">Stride / Trail collection</p>
      <h1>Trail Runner 2</h1>
      <p className="subtitle">Lightweight trail shoes for wherever the path leads.</p>
      <div className="price-line">
        <strong>$145</strong>
        <button className="info-button" type="button" aria-label="Price includes taxes" aria-describedby="tax-tooltip" onFocus={() => setTaxVisible(true)} onBlur={() => setTaxVisible(false)} onMouseEnter={() => setTaxVisible(true)} onKeyDown={(event) => { if (event.key === 'Escape') setTaxVisible(false) }}>i</button>
        <span id="tax-tooltip" role="tooltip" hidden={!taxVisible}>Price includes taxes.</span>
      </div>
      <div className="choice-group">
        <div className="choice-heading"><span>Color</span><strong>{color}</strong></div>
        <div className="swatches" role="radiogroup" aria-label="Color">
          {['Blue', 'Black', 'Grey'].map((item) => (
            <label className={`swatch swatch-${item.toLowerCase()}`} key={item}>
              <input type="radio" name="color" value={item} checked={color === item} onChange={() => setColor(item)} />
              <span aria-hidden="true" />
              <b>{item}</b>
            </label>
          ))}
        </div>
      </div>
      <div className="size-heading">
        <span>Size</span>
        <button type="button" className="text-button" ref={guideButtonRef} onClick={() => setGuideOpen(true)}>Size guide</button>
      </div>
      <div className="size-picker">
        <button type="button" className="size-combobox" role="combobox" aria-label="Size" aria-expanded={sizeOpen} aria-controls="size-options" aria-activedescendant={sizeOpen ? `size-option-${activeSize}` : undefined} onClick={() => setSizeOpen((open) => !open)} onKeyDown={handleSizeKeyDown}>
          {selectedSize ? `US ${selectedSize.value}` : 'Select a size'} <span>⌄</span>
        </button>
        {sizeOpen && (
          <div className="size-options" role="listbox" id="size-options" aria-label="Available sizes">
            {sizes.map((item) => (
                <button type="button" id={`size-option-${sizes.indexOf(item)}`} role="option" aria-selected={size === item.value} aria-disabled={!item.available} disabled={!item.available} key={item.value} onClick={() => { setSize(item.value); setSizeOpen(false) }}>
                US {item.value}{!item.available && ' — sold out'}
              </button>
            ))}
          </div>
        )}
      </div>
      <div className="purchase-row">
        <div className="quantity-control">
          <button type="button" aria-label="Decrease quantity" onClick={() => updateQuantity(quantity - 1)}>−</button>
          <input type="number" min="1" value={quantity} onChange={(event) => updateQuantity(Number(event.target.value))} aria-label="Quantity" />
          <button type="button" aria-label="Increase quantity" onClick={() => updateQuantity(quantity + 1)}>+</button>
        </div>
        <button className="primary-button add-button" type="button" onClick={addToCart}>Add to cart</button>
        <button className={`wishlist-button ${wishlist ? 'is-saved' : ''}`} type="button" aria-label="Wishlist" aria-pressed={wishlist} onClick={() => setWishlist((saved) => !saved)}>♥</button>
      </div>
      {message && <p className={message.includes('Please') ? 'form-message error' : 'form-message'} role={message.includes('Please') ? 'alert' : 'status'}>{message}</p>}
      {guideOpen && <SizeGuide onClose={closeGuide} />}
    </div>
  )
}

function ProductInformation() {
  const [tab, setTab] = useState('details')
  const [openQuestion, setOpenQuestion] = useState(null)
  const questions = [
    ['Is Trail Runner 2 waterproof?', 'The water-resistant upper helps keep you comfortable through light rain and damp trails.'],
    ['How does the fit run?', 'Trail Runner 2 fits true to size with room for natural movement on the trail.'],
    ['Can I return my shoes?', 'Yes. Returns are free within 30 days as long as the shoes are unworn outdoors.'],
  ]
  const panels = {
    details: <>A dependable trail shoe with responsive cushioning, a grippy outsole, and a breathable recycled-mesh upper. Built for daily miles and weekend adventures.</>,
    reviews: <>Loved by trail runners: “Comfortable from the first mile and confident on loose ground.” <strong>4.8 / 5 from 126 reviews.</strong></>,
    shipping: <>Free standard shipping on orders over 75 dollars. Your order ships within 1–2 business days, with free returns within 30 days.</>,
  }

  return (
    <section className="information-section">
      <div className="tabs" role="tablist" aria-label="Product information">
        {Object.keys(panels).map((item) => (
          <button type="button" role="tab" key={item} id={`${item}-tab`} tabIndex={tab === item ? 0 : -1} aria-selected={tab === item} aria-controls={`${item}-panel`} onClick={() => setTab(item)} onKeyDown={(event) => { if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') { const keys = Object.keys(panels); const direction = event.key === 'ArrowRight' ? 1 : -1; const next = keys[(keys.indexOf(item) + direction + keys.length) % keys.length]; setTab(next); document.getElementById(`${next}-tab`)?.focus() } }}>{item[0].toUpperCase() + item.slice(1)}</button>
        ))}
      </div>
      {Object.keys(panels).map((item) => <div className="tabpanel" id={`${item}-panel`} role="tabpanel" aria-labelledby={`${item}-tab`} hidden={tab !== item} key={item}>{panels[item]}</div>)}
      <section className="faq" aria-label="Frequently asked questions">
        <h2>Questions</h2>
        {questions.map(([question, answer], index) => (
          <div className="faq-item" key={question}>
            <h3><button id={`question-${index}`} type="button" aria-expanded={openQuestion === index} aria-controls={`answer-${index}`} onClick={() => setOpenQuestion(openQuestion === index ? null : index)}>{question}<span>+</span></button></h3>
            <div id={`answer-${index}`} className="faq-answer" role="region" aria-labelledby={`question-${index}`} hidden={openQuestion !== index}><p>{answer}</p></div>
          </div>
        ))}
      </section>
    </section>
  )
}

function Footer() {
  return (
    <footer className="site-footer" role="contentinfo">
      <div><p className="footer-title">Customer help</p><a href="/help">Help center</a><a href="/returns">Returns</a></div>
      <div><p className="footer-title">Company</p><a href="/about">About Stride</a><a href="/journal">Our journal</a><a href="/careers">Careers</a></div>
      <div><p className="footer-title">Follow the trail</p><a href="/instagram">Instagram</a></div>
      <p className="copyright">© 2026 Stride. Made for the outdoors.</p>
    </footer>
  )
}

export default function ProductPage() {
  const [cartCount, setCartCount] = useState(0)
  return (
    <div className="product-page">
      <Header cartCount={cartCount} />
      <main>
        <nav className="breadcrumb" aria-label="Breadcrumb">
          <ol><li><a href="/">Shop</a></li><li><a href="/trail">Trail</a></li><li aria-current="page">Trail Runner 2</li></ol>
        </nav>
        <div className="product-layout">
          <ProductCarousel />
          <ProductChoices onAdd={(quantity) => setCartCount((count) => count + quantity)} />
        </div>
        <ProductInformation />
      </main>
      <Footer />
    </div>
  )
}

